#include <iostream>
#include <map>
#include <set>
#include <string>
using namespace std;

int main() {
    map<string, string> faktor;
    faktor["password"] = "bilim";
    faktor["pin"] = "bilim";
    faktor["secret question"] = "bilim";
    faktor["phone"] = "egalik";
    faktor["hardware key"] = "egalik";
    faktor["smart card"] = "egalik";
    faktor["token"] = "egalik";
    faktor["fingerprint"] = "xususiyat";
    faktor["face"] = "xususiyat";
    faktor["iris"] = "xususiyat";
    faktor["voice"] = "xususiyat";
    string satr;
    getline(cin, satr);
    int n = stoi(satr);
    set<string> omillar;
    for (int j = 0; j < n; j++) {
        getline(cin, satr);
        if (!satr.empty() && satr.back() == '\r') satr.pop_back();
        omillar.insert(faktor[satr]);
    }
    cout << (omillar.size() >= 2 ? "MFA" : "NO MFA") << endl;
    return 0;
}
